mapper.select:
SELECT id, title, detail, category, priority, due_date, completed, deleted_at, created_at, updated_at FROM todos
AND deleted_at IS NOT NULL
AND deleted_at IS NULL
AND title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND completed = FALSE
AND due_date >= #{from}
AND due_date <= #{to}
ORDER BY due_date
DESC ASC
LIMIT #{limit} OFFSET #{offset}

